  "chipTips": {
    "Computer vision": [
      "Software that reads images and video — detecting, measuring or classifying what is in them, so a photo or a scan can be handled like data.",
      "이미지와 영상을 읽어 그 안의 대상을 탐지·측정·분류하는 소프트웨어입니다. 사진이나 스캔을 데이터처럼 다룰 수 있게 합니다."
    ],
    "NLP / LLM": [
      "Natural-language processing and large language models: understanding, summarising and generating text — the engine behind assistants, document search and translation.",
      "자연어 처리와 대규모 언어 모델. 텍스트를 이해·요약·생성하는 기술로, 어시스턴트·문서 검색·번역의 엔진입니다."
    ],
    "Workflow AI": [
      "AI placed inside an existing process — classifying inbound documents, drafting replies, routing requests — so people handle the exceptions, not the routine.",
      "기존 업무 흐름 안에 넣는 AI. 문서 분류, 답변 초안, 요청 라우팅을 맡아 사람은 예외만 처리하도록 합니다."
    ],
    "Web platforms": [
      "Browser-based systems with operators and end users on different sides — admin consoles, portals, ordering and management tools.",
      "관리자와 사용자가 양쪽에 있는 브라우저 기반 시스템. 관리 콘솔, 포털, 주문·관리 도구 등입니다."
    ],
    "SaaS": [
      "Software as a service: hosted by us or your provider, billed by subscription, updated centrally rather than installed per machine.",
      "서비스형 소프트웨어. 호스팅되어 구독으로 제공되며, 기기마다 설치하지 않고 중앙에서 업데이트됩니다."
    ],
    "Full-stack": [
      "We build the whole thing — interface, server logic, database and deployment — so one team is accountable end to end.",
      "인터페이스, 서버 로직, 데이터베이스, 배포까지 전부 만듭니다. 한 팀이 끝까지 책임집니다."
    ],
    "LC-OCT": [
      "Line-field confocal optical coherence tomography — a non-invasive skin-imaging method that captures layered, near-histology detail without a biopsy.",
      "라인필드 공초점 광간섭 단층촬영. 생검 없이 조직학 수준의 층별 피부 영상을 비침습적으로 얻는 방법입니다."
    ],
    "Segmentation": [
      "Marking exactly which pixels belong to which structure in an image, so it can be measured or counted rather than just looked at.",
      "이미지의 어느 픽셀이 어느 구조에 속하는지 정확히 구분하는 작업. 보는 데서 끝나지 않고 측정·계수할 수 있게 합니다."
    ],
    "3D reconstruction": [
      "Assembling a stack of 2D image slices into a volume you can rotate, section and measure.",
      "2D 단면 이미지 스택을 회전·단면·측정이 가능한 3차원 볼륨으로 구성합니다."
    ],
    "3D skin analysis": [
      "Measuring skin structure — layer thickness, texture, features — across a reconstructed volume rather than a single slice.",
      "재구성된 볼륨 전체에서 층 두께, 결, 특징 등 피부 구조를 측정합니다. 단일 단면이 아닙니다."
    ],
    "Quantification": [
      "Turning what an image shows into numbers a study can use: thickness, density, area, counts.",
      "이미지가 보여주는 것을 연구에 쓸 수 있는 숫자로 바꿉니다. 두께, 밀도, 면적, 개수."
    ],
    "CT imaging": [
      "Computed tomography — X-ray cross-sections combined into detailed images of the body; here, of the brain.",
      "컴퓨터 단층촬영. X선 단면을 합쳐 신체(여기서는 뇌)의 정밀 영상을 만듭니다."
    ],
    "Visualization": [
      "Presenting image data so a researcher can read it quickly — slice views, overlays, side-by-side comparisons.",
      "연구자가 빠르게 읽을 수 있도록 영상 데이터를 표현합니다. 단면 뷰, 오버레이, 비교 보기."
    ],
    "AI analysis": [
      "Models that highlight regions of interest for a researcher to review — support for the human decision, not a replacement.",
      "연구자가 검토할 관심 영역을 모델이 표시합니다. 사람의 판단을 돕는 도구이며 대체하지 않습니다."
    ],
    "Website embed": [
      "Installed on your existing site with one script tag; no rebuild, styled to match.",
      "스크립트 한 줄로 기존 사이트에 설치합니다. 재구축 없이, 사이트 스타일에 맞춰집니다."
    ],
    "Q&A": [
      "Answers to visitors' questions grounded in your own pages and documents — not the open web.",
      "기관의 페이지와 문서를 근거로 방문자 질문에 답합니다. 외부 웹이 아닙니다."
    ],
    "Document requests": [
      "The assistant collects a request for a form or certificate and hands it to the staff member responsible.",
      "서식·증명서 요청을 접수해 담당 직원에게 전달합니다."
    ],
    "Interface design": [
      "Designing the screens people actually use — layout, hierarchy, states — tested with the people who will use them.",
      "사람들이 실제로 쓰는 화면 설계. 레이아웃, 위계, 상태를 정하고 실제 사용자와 검증합니다."
    ],
    "Design systems": [
      "A shared kit of components, tokens and rules so every screen a team ships looks and behaves the same.",
      "컴포넌트·토큰·규칙의 공용 키트. 팀이 만드는 모든 화면이 같은 모습과 동작을 갖게 합니다."
    ],
    "Prototyping": [
      "Clickable versions of an idea, built fast, so decisions are made on something real before development starts.",
      "아이디어를 빠르게 클릭 가능한 형태로 만들어 개발 전에 실물로 판단합니다."
    ],
    "Legacy migration": [
      "Moving an older system to a current stack without losing its data or the way people work.",
      "데이터와 업무 방식을 잃지 않고 오래된 시스템을 현재 스택으로 옮깁니다."
    ],
    "Integration": [
      "Connecting systems that were never meant to talk — payments, ERPs, government APIs — so data flows without re-typing.",
      "결제, ERP, 공공 API 등 서로 말하지 않던 시스템을 연결해 재입력 없이 데이터가 흐르게 합니다."
    ],
    "Maintenance": [
      "Keeping a live service healthy after launch: updates, monitoring, fixes and small improvements on a schedule.",
      "출시 이후 서비스를 건강하게 유지합니다. 업데이트, 모니터링, 수정, 정기적 개선."
    ]
  },
